// Wait for several calls
let group = DispatchGroup()
for url in urls {
    group.enter()
    fetch(url) { _ in group.leave() }
}
group.notify(queue: .main) { reloadUI() }

// Thread-safe store: many readers, one writer
final class Store: @unchecked Sendable {
    private var dict: [String: Int] = [:]
    private let queue = DispatchQueue(label: "store", attributes: .concurrent)
    func get(_ k: String) -> Int? { queue.sync { dict[k] } }
    func set(_ k: String, _ v: Int) { queue.async(flags: .barrier) { self.dict[k] = v } }
}
